// Primitive CSS: renders `src/theme/tokens/primitives/*.css` and their barrel from primitives.tokens.json, laid out
// by primitives.config.json.

import assert from 'node:assert/strict';
import { declaration } from './dtcg.mjs';

const PRIMITIVES_DIR = 'src/theme/tokens/primitives';

const HEADER = `/*
 * GENERATED by scripts/tokens/generate.mjs from design-system/tokens/source/primitives.tokens.json and
 * primitives.config.json. Do not edit: change those files and run \`pnpm tokens:generate\`.
 */`;

const globToRegExp = (pattern) =>
    new RegExp(
        `^${pattern
            .split('.')
            .map((part) => (part === '*' ? '([^.]+)' : part.replace(/[-/\\^$+?()|[\]{}]/g, '\\$&')))
            .join('\\.')}$`,
    );

// token path -> CSS custom property, by the first matching `cssNames` rule.
const createVarOf = (cssNames) => {
    const rules = Object.entries(cssNames).map(([pattern, template]) => [globToRegExp(pattern), template]);
    return (path) => {
        for (const [regexp, template] of rules) {
            const match = path.match(regexp);
            if (match != null) {
                return template.replace(/\$(\d)/g, (_, n) => match[Number(n)]);
            }
        }
        throw new Error(`No CSS name for token ${path} (primitives.config.json cssNames)`);
    };
};

// Kit-relative path -> generated text. Fails unless every token is placed exactly once.
export const renderPrimitives = ({ tokens, config }) => {
    const varOf = createVarOf(config.cssNames);
    const placed = new Set();
    // A line ending in `;` is CSS; any other line is a token path: that token, or every token under that group.
    const renderLine = (line) => {
        if (line.endsWith(';')) {
            return [line];
        }
        const paths = [...tokens.keys()].filter((path) => path === line || path.startsWith(`${line}.`));
        assert(paths.length > 0, `primitives.config.json: no token at or under ${line}`);
        return paths.map((path) => {
            assert(!placed.has(path), `primitives.config.json: token ${path} is placed twice`);
            placed.add(path);
            return declaration(varOf(path), tokens.get(path), varOf);
        });
    };
    const renderBlock = ([selector, lines]) => {
        const declarations = lines.flatMap(renderLine).map((line) => `    ${line}`);
        return `${selector} {\n${declarations.join('\n')}\n}`;
    };
    const files = new Map();
    for (const [file, blocks] of Object.entries(config.files)) {
        const body = Object.entries(blocks).map(renderBlock).join('\n\n');
        files.set(`${PRIMITIVES_DIR}/${file}`, `${HEADER}\n\n${body}\n`);
    }
    const missing = [...tokens.keys()].filter((path) => !placed.has(path));
    assert.equal(missing.length, 0, `primitives.config.json places no CSS for: ${missing.join(', ')}`);
    const barrel = Object.keys(config.files)
        .map((file) => `@import "./${file}";`)
        .join('\n');
    files.set(`${PRIMITIVES_DIR}/index.css`, `${HEADER}\n\n${barrel}\n`);
    return files;
};
